(()=>{'use strict';
const canvas=document.querySelector('#scene'),ctx=canvas.getContext('2d');
const $=s=>document.querySelector(s),overlay=$('#overlay');let W,H,dpr,ground,last=0,time=0,state='ready',distance=0,carrots=0,speed=300,scroll=0,spawn=1.7,items=[],particles=[],y=0,vy=0,sound=false,audio,best=0,landing=0,takeoff=0,celebrate=0,runId='',rewarded=false;
const buffs=window.BunnyEconomy.createBuffs();
try{best=Number(localStorage.getItem('bunny-run-best'))||0}catch{}$('#best').textContent=best;
function resize(){W=innerWidth;H=Math.max(innerHeight,560);dpr=Math.min(devicePixelRatio||1,2);canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);ground=H*.77}addEventListener('resize',resize);resize();
const rabbitX=()=>state==='ready'?W*.65:Math.max(75,W*.19);
function ellipse(x,y,rx,ry,color,angle=0){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,angle,0,Math.PI*2);ctx.fill()}
function path(points,color){ctx.fillStyle=color;ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();ctx.fill()}
function tone(freq,len=.1,type='sine'){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.65,audio.currentTime+len);g.gain.setValueAtTime(.06,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+len);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+len)}catch{}}
function bunny(x,bottom,scale=1){
 if(y===0)ellipse(x,ground+3,32*scale,6*scale,'#36573822');
 window.BunnySprites.draw(ctx,x,bottom,scale,{state,time,y,vy,landing,takeoff,celebrate});
}
function carrot(x,bottom,s=1){ctx.save();ctx.translate(x,bottom);ctx.scale(s,s);ctx.rotate(.28);path([[-8,-18],[9,-18],[0,7]],'#ed8f42');path([[-1,-18],[-10,-29],[-5,-32],[1,-22],[4,-34],[9,-31],[5,-17]],'#648d45');ctx.strokeStyle='#cf6b2b';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(-4,-12);ctx.lineTo(2,-12);ctx.moveTo(1,-5);ctx.lineTo(4,-5);ctx.stroke();ctx.restore()}
function obstacle(o){if(o.kind==='rock'){ellipse(o.x+o.w/2,ground+4,o.w*.62,6,'#385c3925');path([[o.x,ground],[o.x+3,ground-o.h*.55],[o.x+o.w*.35,ground-o.h],[o.x+o.w*.73,ground-o.h*.93],[o.x+o.w,ground-o.h*.4],[o.x+o.w,ground]],'#899582');path([[o.x+4,ground-o.h*.55],[o.x+o.w*.35,ground-o.h],[o.x+o.w*.65,ground-o.h*.65],[o.x+o.w*.37,ground-o.h*.4]],'#a7b09a')}else{ctx.fillStyle='#a37549';ctx.fillRect(o.x,ground-o.h,o.w,o.h);ellipse(o.x+o.w/2,ground-o.h,o.w/2,6,'#d6b77d');ctx.strokeStyle='#805b3b';ctx.lineWidth=2;for(let i=8;i<o.w;i+=10){ctx.beginPath();ctx.moveTo(o.x+i,ground-4);ctx.lineTo(o.x+i+2,ground-o.h+8);ctx.stroke()}ellipse(o.x+o.w/2,ground-o.h,o.w*.28,3,'#bb965e');path([[o.x-3,ground-o.h+2],[o.x+4,ground-o.h-6],[o.x+13,ground-o.h-3]],'#779443')}}
function background(){const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#e4edd9');sky.addColorStop(.65,'#f5f0d5');sky.addColorStop(1,'#d1dca4');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);ellipse(W*.79,H*.29,52,52,'#f8f5d7');ellipse(W*.79,H*.29,72,72,'#fff8d535');
 for(let i=0;i<5;i++){let x=((i*367-scroll*.08)%(W+400)+W+400)%(W+400)-180;let yy=H*(.19+(i%3)*.07);ellipse(x,yy,46,12,'#ffffff72');ellipse(x+28,yy-7,30,16,'#ffffff72')}
 for(let layer=0;layer<3;layer++){ctx.fillStyle=['#cbd9b4','#b4c999','#94b579'][layer];ctx.beginPath();ctx.moveTo(0,H);for(let x=0;x<=W+8;x+=8){let wave=Math.sin((x+scroll*(.07+layer*.05))/ (220-layer*45)+layer*2)* (35+layer*9);ctx.lineTo(x,H*(.57+layer*.068)+wave)}ctx.lineTo(W,H);ctx.fill()}
 // Distant rounded trees and tiny cottages.
 for(let i=0;i<7;i++){let x=((i*260-scroll*.24)%(W+350)+W+350)%(W+350)-130;let yy=ground-35;ctx.fillStyle='#7f9260';ctx.fillRect(x-3,yy-40,6,45);ellipse(x,yy-58,22,29,'#81a16a');ellipse(x-11,yy-43,19,20,'#81a16a')}
 ctx.fillStyle='#789d5d';ctx.fillRect(0,ground,W,H-ground);ctx.fillStyle='#91ae67';ctx.fillRect(0,ground, W,7);ctx.fillStyle='#698e50';ctx.fillRect(0,ground+8,W,3);
 for(let i=0;i<80;i++){let x=((i*83.3-scroll*.8)%(W+70)+W+70)%(W+70)-30;let yy=ground+18+(i*47%Math.max(30,H-ground-45));ctx.strokeStyle=i%3?'#9db977':'#aec682';ctx.lineWidth=1.4;ctx.beginPath();ctx.moveTo(x,yy);ctx.lineTo(x-3,yy-5);ctx.moveTo(x,yy);ctx.lineTo(x+3,yy-7);ctx.stroke();if(i%6===0){ellipse(x,yy-9,2,3,'#f5e8b5');ellipse(x+3,yy-8,2,2,'#f8efd2')}}
 if(state==='ready'){for(let i=0;i<3;i++)carrot(W*.77+i*45,ground-7,1.1);obstacle({x:W*.91,w:42,h:37,kind:'rock'})}
}
function burst(x,yy,color,n=8){for(let i=0;i<n;i++)particles.push({x,y:yy,vx:(Math.random()-.5)*160,vy:-Math.random()*160,life:.55,color})}
function start(){if(!window.BunnySprites.atlas.naturalWidth)return;document.activeElement?.blur();buffs.reset();runId=globalThis.crypto?.randomUUID?.()||Date.now()+'-'+Math.random();rewarded=false;$('#runReward').hidden=true;landing=0;takeoff=0;celebrate=0;time=0;distance=0;carrots=0;speed=300;items=[];particles=[];y=0;vy=0;spawn=1.8;state='running';overlay.hidden=true;$('#pause').disabled=false;$('#pause').textContent='Ⅱ';$('#pause').setAttribute('aria-label','일시정지');$('#mobileJump').hidden=false;$('#runningNote').hidden=false;$('#announcement').textContent='달리기 시작';updateHUD();last=performance.now()}
function updateHUD(){window.BunnyShop.update({state,speedTime:buffs.remaining.speed,jumpTime:buffs.remaining.jump});$('#distance').textContent=Math.floor(distance);$('#carrots').textContent=carrots;$('#best').textContent=best}
function jump(){if(state==='ready'){start();return}if(state!=='running')return;if(y===0){vy=buffs.jumpImpulse();takeoff=.10;landing=0;tone(530,.14);burst(rabbitX(),ground,'#d4db9a',5)}}
function pause(){document.activeElement?.blur();if(state==='running'){state='paused';overlay.hidden=false;$('#title').innerHTML='잠깐, 쉬어갈까요?';$('#message').innerHTML='토끼가 잠시 숨을 고르고 있어요.<br>준비가 되면 다시 달려요.';$('#start').innerHTML='계속 달리기 <span>▶</span>';$('#introHint').textContent='P 키로도 계속할 수 있어요';$('#pause').textContent='▶';$('#pause').setAttribute('aria-label','계속 달리기');$('#runningNote').hidden=true;$('#mobileJump').hidden=true}else if(state==='paused'){state='running';overlay.hidden=true;$('#pause').textContent='Ⅱ';$('#pause').setAttribute('aria-label','일시정지');$('#mobileJump').hidden=false;last=performance.now()}updateHUD();}
function end(){if(state!=='running'||rewarded)return;rewarded=true;state='over';const reward=window.BunnyShop.reward(runId,Math.floor(distance),carrots);buffs.reset();$('#runReward').hidden=false;$('#runReward').textContent=reward.ok?'🪙 +'+reward.earned.toLocaleString('ko-KR')+' 코인 적립 · 거리 '+Math.floor(Math.floor(distance)/3)+' + 당근 '+carrots:'코인 적립 실패: '+reward.message;tone(160,.3,'triangle');burst(rabbitX(),ground-y-25,'#fff3c5',12);const record=Math.floor(distance);if(record>best){best=record;try{localStorage.setItem('bunny-run-best',best)}catch{}}updateHUD();$('#title').innerHTML='잘 달렸어요!<br>한 번 더 폴짝?';$('#message').innerHTML=`이번 모험은 <strong>${record}m</strong>! 당근 <strong>${carrots}개</strong>를 모았어요.<br>조금 일찍 점프하면 더 멀리 갈 수 있어요.`;$('#start').innerHTML='다시 달리기 <span>↻</span>';$('#introHint').innerHTML='<kbd>Enter</kbd> 키로도 다시 시작';overlay.hidden=false;$('#pause').disabled=true;$('#mobileJump').hidden=true;$('#runningNote').hidden=true;$('#announcement').textContent=`게임 종료. ${record}미터, 당근 ${carrots}개`}
function step(dt){if(state==='paused')return;time+=dt;if(state!=='running')return;landing=Math.max(0,landing-dt);takeoff=Math.max(0,takeoff-dt);celebrate=Math.max(0,celebrate-dt);const speedSeconds=Math.min(dt,buffs.remaining.speed);speed=Math.min(470,300+distance*.32)*(1+(dt>0?.25*speedSeconds/dt:0));distance+=speed*dt/18;buffs.tick(dt);scroll+=speed*dt;const wasAirborne=y>0;vy-=1700*dt;y+=vy*dt;if(y<=0){y=0;vy=0;if(wasAirborne){landing=.16;burst(rabbitX(),ground,'#d4db9a',4)}}spawn-=dt;if(spawn<=0){const w=34+Math.random()*15,h=30+Math.random()*16;items.push({x:W+60,w,h,kind:Math.random()<.5?'rock':'stump'});for(let i=0;i<3;i++)items.push({x:W+50+i*38,w:16,h:24,kind:'carrot',lift:100+Math.sin(i/2*Math.PI)*20});spawn=1.65+Math.random()*.65}
const bx=rabbitX();for(const o of items){o.x-=speed*dt;if(o.kind==='carrot'){if(!o.collected&&Math.abs(o.x-bx)<30&&Math.abs((ground-o.lift)-(ground-y-35))<39){o.collected=true;carrots++;celebrate=.6;tone(870,.09);burst(o.x,ground-o.lift,'#f4b853')}}else if(o.x+o.w>bx-17&&o.x<bx+31&&y+8<o.h){end();break}}items=items.filter(o=>o.x>-90&&!o.collected);if(distance>65)$('#runningNote').hidden=true;updateHUD()}
function frame(now){const dt=Math.min((now-last)/1000||0,.034);last=now;step(dt);background();for(const o of items){if(o.kind==='carrot')carrot(o.x,ground-o.lift+8);else obstacle(o)}const bx=rabbitX();if(y>0)ellipse(bx,ground+3,Math.max(14,32-y*.06),5,'#36573822');bunny(bx,ground-y,state==='ready'?1.65:1);if(state!=='paused'){for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=350*dt;p.life-=dt;ellipse(p.x,p.y,3,3,p.color)}particles=particles.filter(p=>p.life>0)}requestAnimationFrame(frame)}
$('#start').onclick=()=>state==='paused'?pause():start();$('#pause').onclick=pause;$('#sound').onclick=()=>{document.activeElement?.blur();sound=!sound;$('#sound').textContent=sound?'소리 켜짐':'소리 꺼짐';$('#sound').setAttribute('aria-label',sound?'소리 끄기':'소리 켜기');if(sound)tone(660)};
$('#mobileJump').addEventListener('pointerdown',e=>{e.preventDefault();jump()});$('#mobileJump').onclick=()=>{document.activeElement?.blur();jump()};canvas.addEventListener('pointerdown',e=>{e.preventDefault();jump()});addEventListener('keydown',e=>{if(document.querySelector('#installHelp')?.open||document.querySelector('#shopDialog')?.open)return;if(e.target instanceof HTMLButtonElement&&e.code==='Enter')return;if(['Space','ArrowUp','KeyP','Enter'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Digit1'||e.code==='Digit2'){e.preventDefault();usePotion(e.code==='Digit1'?'speed':'jump');}if(e.code==='Space'||e.code==='ArrowUp')jump();if(e.code==='KeyP')pause();if(e.code==='Enter'&&(state==='ready'||state==='over'))start()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='running')pause()});
const startButton=$('#start'),atlas=window.BunnySprites.atlas;
function assetsReady(){startButton.disabled=false;startButton.innerHTML='달리기 시작 <span>▶</span>';}
function assetsFailed(){startButton.disabled=false;startButton.textContent='토끼 이미지 다시 불러오기';$('#message').textContent='이미지를 불러오지 못했어요. 버튼을 눌러 다시 시도해주세요.';startButton.onclick=()=>{startButton.disabled=true;atlas.src='assets/bunny-a-atlas.png?retry='+Date.now()};}
atlas.addEventListener('load',()=>{startButton.onclick=()=>state==='paused'?pause():start();assetsReady()});atlas.addEventListener('error',assetsFailed);
if(atlas.complete&&atlas.naturalWidth)assetsReady();else{startButton.disabled=true;startButton.textContent='토끼가 준비 중이에요…';}
addEventListener('bunny:pause',()=>{if(state==='running')pause()});
function usePotion(kind){if(state!=='running'||(kind!=='speed'&&kind!=='jump')||buffs.remaining[kind]>0)return;if(window.BunnyShop.consume(kind)){buffs.activate(kind);tone(kind==='speed'?720:960,.16);burst(rabbitX(),ground-y-35,kind==='speed'?'#f9d795':'#d9c8fa',10);$('#announcement').textContent=(kind==='speed'?'이동속도':'점프 높이')+' 25% 증가, 10초!';updateHUD();}}
addEventListener('bunny:use-potion',event=>usePotion(event.detail));
requestAnimationFrame(frame);
})();
